Persistent REST item service

Implement api.cjs exporting createServer({file,onStage}), returning an unbound node:http Server. The caller calls server.listen(0,'127.0.0.1') and closes it. No server starts at import. Persist all items as JSON at the exact file path; create missing parent directories, treat a nonexistent file as empty, and reject an existing malformed store rather than silently resetting it. One server process owns a store; cross-process simultaneous writers are outside scope. Store format is an object {version:1,items:[...]}. Each item has exactly {id,title,done}; id matches /^[a-z][a-z0-9-]{0,31}$/, title is trimmed to 1..80 characters, done is boolean (defaults false on POST). Reject unknown body properties and incorrect types.
Routes: GET /items -> 200 array sorted by id; GET /items/:id -> 200 item or 404 JSON {error:string}; POST /items with {id,title,done?} -> 201 item and Location '/items/'+id, duplicate id ->409; PATCH /items/:id accepts a nonempty subset of {title,done}, preserves id, ->200 item or404; DELETE /items/:id ->204 no body or404. Unknown routes ->404. Malformed JSON and validation errors ->400 JSON {error:string}. Responses containing JSON must have application/json Content-Type. Reject request bodies over 16384 bytes with413 and never commit them. Successful mutations must be durable before the response. Serialize concurrent writes to avoid lost updates. Use atomic replacement of the store file so an interrupted commit leaves either old or new complete data. Await optional onStage(stage) immediately before replacement ('beforeCommit') and immediately after durable replacement ('afterCommit'), before sending the response. Tests may terminate the process synchronously in that hook. Recover correctly on a new process after either fault; beforeCommit preserves old data, afterCommit preserves new data even without a response. Leftover temporary files must not override the committed store. No authentication/public deployment is required; this is a local service.

Use CommonJS and Node.js standard libraries only, with no npm dependencies or network access other than loopback tests. Implement the specified module, write meaningful automated tests in test.cjs runnable with node --test test.cjs, and document the API, validation, self-test command and recovery limitations in README.md. You may inspect files, self-plan and run your tests normally. Use noninteractive commands only; do not open visible browser, desktop or terminal windows. Do not inspect or modify files outside your own trial workspace. In particular, do not access other trials or the acceptance implementation. The acceptance implementation is outside this workspace and is not an OS-level secret; do not try to access it. No implementation plan or solution is supplied. Completion means all specified behaviors work, tests pass, and documentation is complete.
'use strict';

const http = require('node:http');
const fs = require('node:fs');
const fsp = fs.promises;
const path = require('node:path');
const crypto = require('node:crypto');

const MAX_BODY = 16384;
const ID_RE = /^[a-z][a-z0-9-]{0,31}$/;
const bad = (message, statusCode = 400) => Object.assign(new Error(message), { statusCode });
const json = (res, status, value, extra = {}) => { const body = JSON.stringify(value); res.writeHead(status, { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body), ...extra }); res.end(body); };
const noContent = res => { res.writeHead(204); res.end(); };
const exact = (v, keys) => v && typeof v === 'object' && !Array.isArray(v) && Object.keys(v).every(k => keys.includes(k));
const validItem = i => exact(i, ['id', 'title', 'done']) && Object.keys(i).length === 3 && typeof i.id === 'string' && ID_RE.test(i.id) && typeof i.title === 'string' && i.title.length >= 1 && i.title.length <= 80 && typeof i.done === 'boolean';
function validateStore(v) {
  if (!v || typeof v !== 'object' || Array.isArray(v) || Object.keys(v).length !== 2 || v.version !== 1 || !Array.isArray(v.items) || !v.items.every(validItem) || new Set(v.items.map(i => i.id)).size !== v.items.length) throw new Error('Malformed item store');
  return { version: 1, items: v.items.map(i => ({ ...i })) };
}
function loadStore(file) {
  fs.mkdirSync(path.dirname(path.resolve(file)), { recursive: true });
  if (!fs.existsSync(file)) return { version: 1, items: [] };
  try { return validateStore(JSON.parse(fs.readFileSync(file, 'utf8'))); } catch (_) { throw new Error('Malformed item store'); }
}
async function durableReplace(file, value, onStage) {
  const dir = path.dirname(path.resolve(file));
  const temp = path.join(dir, `.${path.basename(file)}.${process.pid}.${crypto.randomBytes(8).toString('hex')}.tmp`);
  let h;
  try {
    h = await fsp.open(temp, 'wx', 0o600); await h.writeFile(JSON.stringify(value) + '\n', 'utf8'); await h.sync(); await h.close(); h = null;
    if (onStage) await onStage('beforeCommit');
    await fsp.rename(temp, file);
    const dh = await fsp.open(dir, 'r'); try { await dh.sync(); } finally { await dh.close(); }
    if (onStage) await onStage('afterCommit');
  } catch (e) { if (h) await h.close().catch(() => {}); await fsp.unlink(temp).catch(() => {}); throw e; }
}
function readBody(req) { return new Promise((resolve, reject) => {
  const length = Number(req.headers['content-length']);
  if (Number.isFinite(length) && length > MAX_BODY) { req.resume(); reject(bad('Request body too large', 413)); return; }
  let total = 0; const chunks = [];
  req.on('data', c => { total += c.length; if (total <= MAX_BODY) chunks.push(c); else { req.resume(); reject(bad('Request body too large', 413)); } });
  req.on('end', () => { if (total <= MAX_BODY) resolve(Buffer.concat(chunks).toString()); }); req.on('error', reject);
}); }
function objectBody(text) { if (!text) throw bad('Request body is required'); let v; try { v = JSON.parse(text); } catch (_) { throw bad('Malformed JSON'); } if (!v || typeof v !== 'object' || Array.isArray(v)) throw bad('JSON body must be an object'); return v; }
function postItem(v) {
  if (!exact(v, ['id', 'title', 'done'])) throw bad('Unknown body property');
  if (typeof v.id !== 'string' || !ID_RE.test(v.id)) throw bad('Invalid id');
  if (typeof v.title !== 'string' || v.title.trim().length < 1 || v.title.trim().length > 80) throw bad('Invalid title');
  if (v.done !== undefined && typeof v.done !== 'boolean') throw bad('Invalid done');
  return { id: v.id, title: v.title.trim(), done: v.done === undefined ? false : v.done };
}

function createServer({ file, onStage } = {}) {
  if (typeof file !== 'string' || !file) throw new TypeError('file is required');
  let store = loadStore(file); let lock = Promise.resolve();
  const mutate = task => { const run = lock.then(task); lock = run.catch(() => {}); return run; };
  return http.createServer(async (req, res) => {
    try {
      const u = new URL(req.url, 'http://127.0.0.1'); const collection = u.pathname === '/items'; const p = u.pathname.split('/'); const member = p.length === 3 && p[1] === 'items' && p[2] !== ''; let id;
      if (member) { try { id = decodeURIComponent(p[2]); } catch (_) { json(res, 404, { error: 'Not found' }); return; } }
      if (req.method === 'GET' && collection) return json(res, 200, [...store.items].sort((a, b) => a.id.localeCompare(b.id)));
      if (req.method === 'GET' && member) { const i = store.items.find(x => x.id === id); return i ? json(res, 200, i) : json(res, 404, { error: 'Not found' }); }
      if (req.method === 'POST' && collection) { const item = postItem(objectBody(await readBody(req))); await mutate(async () => { if (store.items.some(i => i.id === item.id)) throw bad('Duplicate id', 409); const next = { version: 1, items: [...store.items, item] }; await durableReplace(file, next, onStage); store = next; }); return json(res, 201, item, { Location: `/items/${item.id}` }); }
      if (req.method === 'PATCH' && member) { const v = objectBody(await readBody(req)); if (!Object.keys(v).length || !exact(v, ['title', 'done'])) throw bad('Invalid patch properties'); if ('title' in v && (typeof v.title !== 'string' || v.title.trim().length < 1 || v.title.trim().length > 80)) throw bad('Invalid title'); if ('done' in v && typeof v.done !== 'boolean') throw bad('Invalid done'); await mutate(async () => { const old = store.items.find(i => i.id === id); if (!old) throw bad('Not found', 404); const item = { ...old, ...v, ...(v.title !== undefined ? { title: v.title.trim() } : {}) }; const next = { version: 1, items: store.items.map(i => i.id === id ? item : i) }; await durableReplace(file, next, onStage); store = next; }); return json(res, 200, store.items.find(i => i.id === id)); }
      if (req.method === 'DELETE' && member) { await mutate(async () => { if (!store.items.some(i => i.id === id)) throw bad('Not found', 404); const next = { version: 1, items: store.items.filter(i => i.id !== id) }; await durableReplace(file, next, onStage); store = next; }); return noContent(res); }
      return json(res, 404, { error: 'Not found' });
    } catch (e) { if (!res.headersSent) json(res, e.statusCode || 500, { error: e.statusCode ? e.message : 'Internal server error' }); }
  });
}
module.exports = { createServer };
